 */
@Test
public void checkLength() {
    File[] files = this.tempFile.isDirectory() ? this.tempFile.listFiles() : new File[] { this.tempFile };
    Arrays.sort(files);
    for (int fileIndex = 0; fileIndex < this.parallelism; fileIndex++) {
