@Test
public void testConfigurationYAML() {
    File tmpDir = getTmpDir();
    File confFile1 = createRandomFile(tmpDir, ".yaml");
    File confFile2 = createRandomFile(tmpDir, ".yml");
    try {
        try {
            PrintWriter pw1 = new PrintWriter(confFile1);
            PrintWriter pw2 = new PrintWriter(confFile2);
            // should be skipped
            pw1.println("###########################");
            // should be skipped
            pw1.println("# Some : comments : to skip");
            // should be skipped
            pw1.println("###########################");
            // OK, simple correct case
            pw1.println("mykey1: myvalue1");
            // OK, whitespace before colon is correct
            pw1.println("mykey2       : myvalue2");
            // SKIP, missing white space after colon
            pw1.println("mykey3:myvalue3");
            // SKIP
            pw1.println(" some nonsense without colon and whitespace separator");
            // SKIP
            pw1.println(" :  ");
            // SKIP
            pw1.println("   ");
            // OK, skip comments only
            pw1.println("mykey4: myvalue4# some comments");
            // OK, trim unnecessary whitespace
            pw1.println("   mykey5    :    myvalue5    ");
            // OK, only use first ': ' as separator
            pw1.println("mykey6: my: value6");
            // SKIP, no value provided
            pw1.println("mykey7: ");
            // SKIP, no key provided
            pw1.println(": myvalue8");
            // OK
            pw2.println("mykey9: myvalue9");
            // OK, overwrite last value
            pw2.println("mykey9: myvalue10");
            pw1.close();
            pw2.close();
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        }
        GlobalConfiguration.loadConfiguration(tmpDir.getAbsolutePath());
        Configuration conf = GlobalConfiguration.getConfiguration();
        // all distinct keys from confFile1 + confFile2 key
        assertEquals(6, conf.keySet().size());
        // keys 1, 2, 4, 5, 6, 7, 8 should be OK and match the expected values
        assertEquals("myvalue1", conf.getString("mykey1", null));
        assertEquals("myvalue2", conf.getString("mykey2", null));
        assertEquals("null", conf.getString("mykey3", "null"));
        assertEquals("myvalue4", conf.getString("mykey4", null));
        assertEquals("myvalue5", conf.getString("mykey5", null));
        assertEquals("my: value6", conf.getString("mykey6", null));
        assertEquals("null", conf.getString("mykey7", "null"));
        assertEquals("null", conf.getString("mykey8", "null"));
        assertEquals("myvalue10", conf.getString("mykey9", null));
    } finally {
        confFile1.delete();
        confFile2.delete();
        tmpDir.delete();
    }
}

