    p = new Path(path);
    u = p.toUri();
    p = p.makeQualified(FileSystem.get(u));
    u = p.toUri();
    assertEquals("file", u.getScheme());
    assertEquals(null, u.getAuthority());
    assertEquals(path, u.getPath());
}

