        }
        DataInputStream in = new DataInputStream(new ByteArrayInputStream(new byte[segmentSize / 2]));
        try {
            int pos = 0;
            while (pos < pageSize) {
                int len = random.nextInt(segmentSize / 10);
                len = Math.min(len, pageSize - pos);
                seg.put(in, pos, len);
                pos += len;
            }
            fail("Should fail with an EOFException");
