    } else {
        TupleTypeInfo<?> tinfo = (TupleTypeInfo<?>) info;
        Assert.assertEquals(BasicTypeInfo.INT_TYPE_INFO, tinfo.getTypeAt(0));
        Assert.assertEquals(BasicTypeInfo.STRING_TYPE_INFO, tinfo.getTypeAt(1));
