@Test
public void testJoinProjection21() {
    final ExecutionEnvironment env = ExecutionEnvironment.getExecutionEnvironment();
    DataSet<Tuple5<Integer, Long, String, Long, Integer>> ds1 = env.fromCollection(emptyTupleData, tupleTypeInfo);
    DataSet<Tuple5<Integer, Long, String, Long, Integer>> ds2 = env.fromCollection(emptyTupleData, tupleTypeInfo);
    // should work
    try {
        ds1.join(ds2).where(0).equalTo(0).projectFirst(0);
    } catch (Exception e) {
        Assert.fail();
    }
    // should not work: field index is out of bounds of input tuple
    try {
        ds1.join(ds2).where(0).equalTo(0).projectFirst(-1);
        Assert.fail();
    } catch (IndexOutOfBoundsException iob) {
        // we're good here
    } catch (Exception e) {
        Assert.fail();
    }
    // should not work: field index is out of bounds of input tuple
    try {
        ds1.join(ds2).where(0).equalTo(0).project(9);
        Assert.fail();
    } catch (IndexOutOfBoundsException iob) {
        // we're good here
    } catch (Exception e) {
        Assert.fail();
    }
}

