@Test
public void testAssignSlotSharingGroup() {
    try {
        JobVertex v1 = new JobVertex("v1");
        JobVertex v2 = new JobVertex("v2");
        JobVertex v3 = new JobVertex("v3");
        JobVertex v4 = new JobVertex("v4");
        JobVertex v5 = new JobVertex("v5");
        v1.setParallelism(4);
        v2.setParallelism(5);
        v3.setParallelism(7);
        v4.setParallelism(1);
        v5.setParallelism(11);
        v2.connectNewDataSetAsInput(v1, DistributionPattern.POINTWISE);
        v5.connectNewDataSetAsInput(v4, DistributionPattern.POINTWISE);
        SlotSharingGroup jg1 = new SlotSharingGroup();
        v2.setSlotSharingGroup(jg1);
        v3.setSlotSharingGroup(jg1);
        SlotSharingGroup jg2 = new SlotSharingGroup();
        v4.setSlotSharingGroup(jg2);
        v5.setSlotSharingGroup(jg2);
        List<JobVertex> vertices = new ArrayList<JobVertex>(Arrays.asList(v1, v2, v3, v4, v5));
        ExecutionGraph eg = new ExecutionGraph(TestingUtils.defaultExecutionContext(), new JobID(), "test job", new Configuration(), ExecutionConfigTest.getSerializedConfig(), AkkaUtils.getDefaultTimeout(), new NoRestartStrategy());
        eg.attachJobGraph(vertices);
        // verify that the vertices are all in the same slot sharing group
        SlotSharingGroup group1 = null;
        SlotSharingGroup group2 = null;
        // verify that v1 tasks have no slot sharing group
        assertNull(eg.getJobVertex(v1.getID()).getSlotSharingGroup());
        // v2 and v3 are shared
        group1 = eg.getJobVertex(v2.getID()).getSlotSharingGroup();
        assertNotNull(group1);
        assertEquals(group1, eg.getJobVertex(v3.getID()).getSlotSharingGroup());
        assertEquals(2, group1.getJobVertexIds().size());
        assertTrue(group1.getJobVertexIds().contains(v2.getID()));
        assertTrue(group1.getJobVertexIds().contains(v3.getID()));
        // v4 and v5 are shared
        group2 = eg.getJobVertex(v4.getID()).getSlotSharingGroup();
        assertNotNull(group2);
        assertEquals(group2, eg.getJobVertex(v5.getID()).getSlotSharingGroup());
        assertEquals(2, group1.getJobVertexIds().size());
        assertTrue(group2.getJobVertexIds().contains(v4.getID()));
        assertTrue(group2.getJobVertexIds().contains(v5.getID()));
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

@Test
public void testFileReuseForNextTask() {
    try {
        final JobID jobID = new JobID();
        final String fileName = "test_file";
        final String filePath = f.toURI().toString();
        // copy / create the file
        Future<Path> copyResult = fileCache.createTmpFile(fileName, new DistributedCacheEntry(filePath, false), jobID);
        copyResult.get();
        // get another reference to the file
        Future<Path> copyResult2 = fileCache.createTmpFile(fileName, new DistributedCacheEntry(filePath, false), jobID);
        // this should be available immediately
        assertTrue(copyResult2.isDone());
        // delete the file
        fileCache.deleteTmpFile(fileName, jobID);
        // file should not yet be deleted
        assertTrue(fileCache.holdsStillReference(fileName, jobID));
        // delete the second reference
        fileCache.deleteTmpFile(fileName, jobID);
        // file should still not be deleted, but remain for a bit
        assertTrue(fileCache.holdsStillReference(fileName, jobID));
        fileCache.createTmpFile(fileName, new DistributedCacheEntry(filePath, false), jobID);
        fileCache.deleteTmpFile(fileName, jobID);
        // after a while, the file should disappear
        long deadline = System.currentTimeMillis() + 20000;
        do {
            Thread.sleep(5500);
        } while (fileCache.holdsStillReference(fileName, jobID) && System.currentTimeMillis() < deadline);
        assertFalse(fileCache.holdsStillReference(fileName, jobID));
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

