            assertFalse(slot.isAlive());
            assertTrue(slot.isCanceled());
            assertFalse(slot.isReleased());
            slot.markReleased();
            assertFalse(slot.isAlive());
            assertTrue(slot.isCanceled());
            assertTrue(slot.isReleased());
        }
    } catch (Exception e) {
