            assertTrue(slot.markCancelled());
            assertTrue(slot.markReleased());
            assertFalse(slot.setExecutedVertex(ev));
            assertNull(slot.getExecutedVertex());
        }
        // assign to released
        {
            SimpleSlot slot = getSlot();
            slot.releaseSlot();
            assertFalse(slot.setExecutedVertex(ev));
            assertNull(slot.getExecutedVertex());
        }
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

