@Test
public void testCheckpointCallsInOrder() {
    try {
        Task task = createTask();
        task.startTaskThread();
        awaitLatch.await();
        for (int i = 1; i <= NUM_CALLS; i++) {
            task.triggerCheckpointBarrier(i, 156865867234L);
        }
        triggerLatch.await();
        assertFalse(task.isCanceledOrFailed());
        ExecutionState currentState = task.getExecutionState();
        if (currentState != ExecutionState.RUNNING && currentState != ExecutionState.FINISHED) {
            fail("Task should be RUNNING or FINISHED, but is " + currentState);
        }
        task.cancelExecution();
        task.getExecutingThread().join();
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

@Test
public void testMixedAsyncCallsInOrder() {
    try {
        Task task = createTask();
        task.startTaskThread();
        awaitLatch.await();
        for (int i = 1; i <= NUM_CALLS; i++) {
            task.triggerCheckpointBarrier(i, 156865867234L);
            task.notifyCheckpointComplete(i);
        }
        triggerLatch.await();
        assertFalse(task.isCanceledOrFailed());
        ExecutionState currentState = task.getExecutionState();
        if (currentState != ExecutionState.RUNNING && currentState != ExecutionState.FINISHED) {
            fail("Task should be RUNNING or FINISHED, but is " + currentState);
        }
        task.cancelExecution();
        task.getExecutingThread().join();
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

/**
 * Tests that a task waiting on an async producer/consumer that is stuck
 * in a blocking buffer request can be properly cancelled.
 *
 * <p>This is currently required for the Flink Kafka sources, which spawn
 * a separate Thread consuming from Kafka and producing the intermediate
 * streams in the spawned Thread instead of the main task Thread.
 */
@Test
public void testCancelAsyncProducerAndConsumer() throws Exception {
    Deadline deadline = new FiniteDuration(2, TimeUnit.MINUTES).fromNow();
    TestingCluster flink = null;
    try {
        // Cluster
        Configuration config = new Configuration();
        config.setInteger(ConfigConstants.LOCAL_NUMBER_TASK_MANAGER, 1);
        config.setInteger(ConfigConstants.TASK_MANAGER_NUM_TASK_SLOTS, 1);
        config.setInteger(ConfigConstants.TASK_MANAGER_MEMORY_SEGMENT_SIZE_KEY, 4096);
        config.setInteger(ConfigConstants.TASK_MANAGER_NETWORK_NUM_BUFFERS_KEY, 8);
        flink = new TestingCluster(config, true);
        flink.start();
        // Job with async producer and consumer
        JobVertex producer = new JobVertex("AsyncProducer");
        producer.setParallelism(1);
        producer.setInvokableClass(AsyncProducer.class);
        JobVertex consumer = new JobVertex("AsyncConsumer");
        consumer.setParallelism(1);
        consumer.setInvokableClass(AsyncConsumer.class);
        consumer.connectNewDataSetAsInput(producer, DistributionPattern.POINTWISE);
        SlotSharingGroup slot = new SlotSharingGroup(producer.getID(), consumer.getID());
        producer.setSlotSharingGroup(slot);
        consumer.setSlotSharingGroup(slot);
        JobGraph jobGraph = new JobGraph(producer, consumer);
        // Submit job and wait until running
        ActorGateway jobManager = flink.getLeaderGateway(deadline.timeLeft());
        flink.submitJobDetached(jobGraph);
        Object msg = new WaitForAllVerticesToBeRunning(jobGraph.getJobID());
        Future<?> runningFuture = jobManager.ask(msg, deadline.timeLeft());
        Await.ready(runningFuture, deadline.timeLeft());
        // Wait for blocking requests, cancel and wait for cancellation
        msg = new NotifyWhenJobStatus(jobGraph.getJobID(), JobStatus.CANCELED);
        Future<?> cancelledFuture = jobManager.ask(msg, deadline.timeLeft());
        boolean producerBlocked = false;
        for (int i = 0; i < 50; i++) {
            Thread thread = ASYNC_PRODUCER_THREAD;
            if (thread != null && thread.isAlive()) {
                StackTraceElement[] stackTrace = thread.getStackTrace();
                producerBlocked = isInBlockingBufferRequest(stackTrace);
            }
            if (producerBlocked) {
                break;
            } else {
                // Retry
                Thread.sleep(500);
            }
        }
        // Verify that async producer is in blocking request
        assertTrue("Producer thread is not blocked.", producerBlocked);
        boolean consumerBlocked = false;
        for (int i = 0; i < 50; i++) {
            Thread thread = ASYNC_CONSUMER_THREAD;
            if (thread != null && thread.isAlive()) {
                StackTraceElement[] stackTrace = thread.getStackTrace();
                consumerBlocked = isInBlockingQueuePoll(stackTrace);
            }
            if (consumerBlocked) {
                break;
            } else {
                // Retry
                Thread.sleep(500);
            }
        }
        // Verify that async consumer is in blocking request
        assertTrue("Consumer thread is not blocked.", consumerBlocked);
        msg = new CancelJob(jobGraph.getJobID());
        Future<?> cancelFuture = jobManager.ask(msg, deadline.timeLeft());
        Await.ready(cancelFuture, deadline.timeLeft());
        Await.ready(cancelledFuture, deadline.timeLeft());
        // Verify the expected Exceptions
        assertNotNull(ASYNC_PRODUCER_EXCEPTION);
        assertEquals(IllegalStateException.class, ASYNC_PRODUCER_EXCEPTION.getClass());
        assertNotNull(ASYNC_CONSUMER_EXCEPTION);
        assertEquals(IllegalStateException.class, ASYNC_CONSUMER_EXCEPTION.getClass());
    } finally {
        if (flink != null) {
            flink.shutdown();
        }
    }
}

@Test
public void testCancelUnion() throws Exception {
    // Test config
    int numberOfSources = 8;
    int sourceParallelism = 4;
    TestingCluster flink = null;
    try {
        // Start a cluster for the given test config
        final Configuration config = new Configuration();
        config.setInteger(ConfigConstants.LOCAL_NUMBER_TASK_MANAGER, 2);
        config.setInteger(ConfigConstants.TASK_MANAGER_NUM_TASK_SLOTS, sourceParallelism);
        config.setString(ConfigConstants.AKKA_ASK_TIMEOUT, TestingUtils.DEFAULT_AKKA_ASK_TIMEOUT());
        config.setInteger(ConfigConstants.TASK_MANAGER_MEMORY_SEGMENT_SIZE_KEY, 4096);
        config.setInteger(ConfigConstants.TASK_MANAGER_NETWORK_NUM_BUFFERS_KEY, 2048);
        flink = new TestingCluster(config, false);
        flink.start();
        // Setup
        final JobGraph jobGraph = new JobGraph("Cancel Big Union");
        JobVertex[] sources = new JobVertex[numberOfSources];
        SlotSharingGroup group = new SlotSharingGroup();
        // Create multiple sources
        for (int i = 0; i < sources.length; i++) {
            sources[i] = new JobVertex("Source " + i);
            sources[i].setInvokableClass(InfiniteSource.class);
            sources[i].setParallelism(sourceParallelism);
            sources[i].setSlotSharingGroup(group);
            jobGraph.addVertex(sources[i]);
            group.addVertexToGroup(sources[i].getID());
        }
        // Union all sources
        JobVertex union = new JobVertex("Union");
        union.setInvokableClass(AgnosticUnion.class);
        union.setParallelism(sourceParallelism);
        jobGraph.addVertex(union);
        // Each source creates a separate result
        for (JobVertex source : sources) {
            union.connectNewDataSetAsInput(source, DistributionPattern.POINTWISE, ResultPartitionType.PIPELINED);
        }
        // run the job
        flink.submitJobDetached(jobGraph);
        // Wait for the job to make some progress and then cancel
        awaitRunning(flink.getLeaderGateway(TestingUtils.TESTING_DURATION()), jobGraph.getJobID(), TestingUtils.TESTING_DURATION());
        Thread.sleep(5000);
        cancelJob(flink.getLeaderGateway(TestingUtils.TESTING_DURATION()), jobGraph.getJobID(), TestingUtils.TESTING_DURATION());
        // Wait for the job to be cancelled
        JobManagerActorTestUtils.waitForJobStatus(jobGraph.getJobID(), JobStatus.CANCELED, flink.getLeaderGateway(TestingUtils.TESTING_DURATION()), TestingUtils.TESTING_DURATION());
    } finally {
        if (flink != null) {
            flink.shutdown();
        }
    }
}

