@Test
public void testCheckpointAndRestore() {
    try {
        final int NUM_ELEMENTS = 10000;
        List<Integer> data = new ArrayList<Integer>(NUM_ELEMENTS);
        List<Integer> result = new ArrayList<Integer>(NUM_ELEMENTS);
        for (int i = 0; i < NUM_ELEMENTS; i++) {
            data.add(i);
        }
        final FromElementsFunction<Integer> source = new FromElementsFunction<Integer>(IntSerializer.INSTANCE, data);
        final FromElementsFunction<Integer> sourceCopy = CommonTestUtils.createCopySerializable(source);
        final SourceFunction.SourceContext<Integer> ctx = new ListSourceContext<Integer>(result, 2L);
        final Throwable[] error = new Throwable[1];
        // run the source asynchronously
        Thread runner = new Thread() {

            @Override
            public void run() {
                try {
                    source.run(ctx);
                } catch (Throwable t) {
                    error[0] = t;
                }
            }
        };
        runner.start();
        // wait for a bit
        Thread.sleep(1000);
        // make a checkpoint
        int count;
        List<Integer> checkpointData = new ArrayList<Integer>(NUM_ELEMENTS);
        synchronized (ctx.getCheckpointLock()) {
            count = source.snapshotState(566, System.currentTimeMillis());
            checkpointData.addAll(result);
        }
        // cancel the source
        source.cancel();
        runner.join();
        // check for errors
        if (error[0] != null) {
            System.err.println("Error in asynchronous source runner");
            error[0].printStackTrace();
            fail("Error in asynchronous source runner");
        }
        // recovery run
        SourceFunction.SourceContext<Integer> newCtx = new ListSourceContext<Integer>(checkpointData);
        sourceCopy.restoreState(count);
        sourceCopy.run(newCtx);
        assertEquals(data, checkpointData);
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

@Test
public void testMonotonousTimestamps() {
    AssignerWithPeriodicWatermarks<String> assigner = new IngestionTimeExtractor<>();
    long maxRecordSoFar = 0L;
    long maxWatermarkSoFar = 0L;
    for (int i = 0; i < 1343; i++) {
        if (i % 7 == 1) {
            Watermark mark = assigner.getCurrentWatermark();
            assertNotNull(mark);
            // increasing watermarks
            assertTrue(mark.getTimestamp() >= maxWatermarkSoFar);
            maxWatermarkSoFar = mark.getTimestamp();
            // tight watermarks
            assertTrue(mark.getTimestamp() >= maxRecordSoFar - 1);
        } else {
            long next = assigner.extractTimestamp("a", Long.MIN_VALUE);
            // increasing timestamps
            assertTrue(next >= maxRecordSoFar);
            // timestamps are never below or at the watermark
            assertTrue(next > maxWatermarkSoFar);
            maxRecordSoFar = next;
        }
        if (i % 9 == 0) {
            try {
                Thread.sleep(1);
            } catch (InterruptedException ignored) {
            }
        }
    }
}

