    operator.processingTimeTimers.add(timer1);
    operator.processingTimeTimers.add(timer2);
    operator.processingTimeTimers.add(timer3);
    operator.processingTimeTimersQueue.add(timer1);
    operator.processingTimeTimersQueue.add(timer2);
    operator.processingTimeTimersQueue.add(timer3);
    operator.processingTimeTimerTimestamps.add(1L, 10);
    operator.processingTimeTimerTimestamps.add(2L, 5);
    operator.processingTimeTimerTimestamps.add(3L, 1);
    StreamTaskState snapshot = testHarness.snapshot(0, 0);
    WindowOperator<String, Tuple2<String, Integer>, Tuple2<String, Integer>, Tuple2<String, Integer>, TimeWindow> otherOperator = new WindowOperator<>(SlidingEventTimeWindows.of(Time.of(WINDOW_SIZE, TimeUnit.SECONDS), Time.of(WINDOW_SLIDE, TimeUnit.SECONDS)), new TimeWindow.Serializer(), new TupleKeySelector(), BasicTypeInfo.STRING_TYPE_INFO.createSerializer(new ExecutionConfig()), stateDesc, new InternalSingleValueWindowFunction<>(new PassThroughWindowFunction<String, TimeWindow, Tuple2<String, Integer>>()), EventTimeTrigger.create());
