/**
 * This test ensures that the SourceStreamTask properly serializes checkpointing
 * and element emission. This also verifies that there are no concurrent invocations
 * of the checkpoint method on the source operator.
 *
 * The source emits elements and performs checkpoints. We have several checkpointer threads
 * that fire checkpoint requests at the source task.
 *
 * If element emission and checkpointing are not in series the count of elements at the
 * beginning of a checkpoint and at the end of a checkpoint are not the same because the
 * source kept emitting elements while the checkpoint was ongoing.
 */
@Test
@SuppressWarnings("unchecked")
public void testCheckpointing() throws Exception {
    final int NUM_ELEMENTS = 100;
    final int NUM_CHECKPOINTS = 100;
    final int NUM_CHECKPOINTERS = 1;
    // in ms
    final int CHECKPOINT_INTERVAL = 5;
    // how many random values we sum up in storeCheckpoint
    final int SOURCE_CHECKPOINT_DELAY = 1000;
    // in ms
    final int SOURCE_READ_DELAY = 1;
    ExecutorService executor = Executors.newFixedThreadPool(10);
    try {
        final TupleTypeInfo<Tuple2<Long, Integer>> typeInfo = new TupleTypeInfo<Tuple2<Long, Integer>>(BasicTypeInfo.LONG_TYPE_INFO, BasicTypeInfo.INT_TYPE_INFO);
        final SourceStreamTask<Tuple2<Long, Integer>, SourceFunction<Tuple2<Long, Integer>>, StreamSource<Tuple2<Long, Integer>, SourceFunction<Tuple2<Long, Integer>>>> sourceTask = new SourceStreamTask<>();
        final StreamTaskTestHarness<Tuple2<Long, Integer>> testHarness = new StreamTaskTestHarness<Tuple2<Long, Integer>>(sourceTask, typeInfo);
        StreamConfig streamConfig = testHarness.getStreamConfig();
        StreamSource<Tuple2<Long, Integer>, ?> sourceOperator = new StreamSource<>(new MockSource(NUM_ELEMENTS, SOURCE_CHECKPOINT_DELAY, SOURCE_READ_DELAY));
        streamConfig.setStreamOperator(sourceOperator);
        // prepare the
        Future<Boolean>[] checkpointerResults = new Future[NUM_CHECKPOINTERS];
        // invoke this first, so the tasks are actually running when the checkpoints are scheduled
        testHarness.invoke();
        for (int i = 0; i < NUM_CHECKPOINTERS; i++) {
            checkpointerResults[i] = executor.submit(new Checkpointer(NUM_CHECKPOINTS, CHECKPOINT_INTERVAL, sourceTask));
        }
        testHarness.waitForTaskCompletion();
        // Get the result from the checkpointers, if these threw an exception it
        // will be rethrown here
        for (int i = 0; i < NUM_CHECKPOINTERS; i++) {
            if (!checkpointerResults[i].isDone()) {
                checkpointerResults[i].cancel(true);
            }
            if (!checkpointerResults[i].isCancelled()) {
                checkpointerResults[i].get();
            }
        }
        List<Tuple2<Long, Integer>> resultElements = TestHarnessUtil.getRawElementsFromOutput(testHarness.getOutput());
        Assert.assertEquals(NUM_ELEMENTS, resultElements.size());
    } finally {
        executor.shutdown();
    }
}

/**
 * This ensures that asynchronous state handles are actually materialized asynchonously.
 *
 * <p>We use latches to block at various stages and see if the code still continues through
 * the parts that are not asynchronous. If the checkpoint is not done asynchronously the
 * test will simply lock forever.
 * @throws Exception
 */
@Test
public void testAsyncCheckpoints() throws Exception {
    final OneShotLatch delayCheckpointLatch = new OneShotLatch();
    final OneShotLatch ensureCheckpointLatch = new OneShotLatch();
    final OneInputStreamTask<String, String> task = new OneInputStreamTask<>();
    final OneInputStreamTaskTestHarness<String, String> testHarness = new OneInputStreamTaskTestHarness<>(task, BasicTypeInfo.STRING_TYPE_INFO, BasicTypeInfo.STRING_TYPE_INFO);
    StreamConfig streamConfig = testHarness.getStreamConfig();
    streamConfig.setStreamOperator(new AsyncCheckpointOperator());
    StreamMockEnvironment mockEnv = new StreamMockEnvironment(testHarness.jobConfig, testHarness.taskConfig, testHarness.memorySize, new MockInputSplitProvider(), testHarness.bufferSize) {

        @Override
        public ExecutionConfig getExecutionConfig() {
            return testHarness.executionConfig;
        }

        @Override
        public void acknowledgeCheckpoint(long checkpointId) {
            super.acknowledgeCheckpoint(checkpointId);
        }

        @Override
        public void acknowledgeCheckpoint(long checkpointId, StateHandle<?> state) {
            super.acknowledgeCheckpoint(checkpointId, state);
            // block on the latch, to verify that triggerCheckpoint returns below,
            // even though the async checkpoint would not finish
            try {
                delayCheckpointLatch.await();
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
            assertTrue(state instanceof StreamTaskStateList);
            StreamTaskStateList stateList = (StreamTaskStateList) state;
            // should be only one state
            StreamTaskState taskState = stateList.getState(this.getUserClassLoader())[0];
            StateHandle<?> operatorState = taskState.getOperatorState();
            assertTrue("It must be a TestStateHandle", operatorState instanceof TestStateHandle);
            TestStateHandle testState = (TestStateHandle) operatorState;
            assertEquals(42, testState.checkpointId);
            assertEquals(17, testState.timestamp);
            // we now know that the checkpoint went through
            ensureCheckpointLatch.trigger();
        }
    };
    testHarness.invoke(mockEnv);
    // wait for the task to be running
    for (Field field : StreamTask.class.getDeclaredFields()) {
        if (field.getName().equals("isRunning")) {
            field.setAccessible(true);
            while (!field.getBoolean(task)) {
                Thread.sleep(10);
            }
        }
    }
    task.triggerCheckpoint(42, 17);
    // now we allow the checkpoint
    delayCheckpointLatch.trigger();
    // wait for the checkpoint to go through
    ensureCheckpointLatch.await();
    testHarness.endInput();
    testHarness.waitForTaskCompletion();
}

/**
 * This test checks that cancel calls that are issued before the operator is
 * instantiated still lead to proper canceling.
 */
@Test
public void testEarlyCanceling() {
    try {
        StreamConfig cfg = new StreamConfig(new Configuration());
        cfg.setStreamOperator(new SlowlyDeserializingOperator());
        Task task = createTask(SourceStreamTask.class, cfg);
        task.startTaskThread();
        // wait until the task thread reached state RUNNING
        while (task.getExecutionState() == ExecutionState.CREATED || task.getExecutionState() == ExecutionState.DEPLOYING) {
            Thread.sleep(5);
        }
        // make sure the task is really running
        if (task.getExecutionState() != ExecutionState.RUNNING) {
            fail("Task entered state " + task.getExecutionState() + " with error " + ExceptionUtils.stringifyException(task.getFailureCause()));
        }
        // send a cancel. because the operator takes a long time to deserialize, this should
        // hit the task before the operator is deserialized
        task.cancelExecution();
        // the task should reach state canceled eventually
        assertTrue(task.getExecutionState() == ExecutionState.CANCELING || task.getExecutionState() == ExecutionState.CANCELED);
        task.getExecutingThread().join(60000);
        assertFalse("Task did not cancel", task.getExecutingThread().isAlive());
        assertEquals(ExecutionState.CANCELED, task.getExecutionState());
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

